package org.example;

import java.util.Arrays;
import java.util.List;
import java.util.Random;

public class GeradorJogador {
    private List<String> nomes;
    private List<String> sobrenomes;
    private List<String> posicoes;
    private List<String> times;
    private Random random;

    public GeradorJogador() {
        this.random = new Random();
        inicializarListas();
    }

    private void inicializarListas() {
        nomes = Arrays.asList(
            "Cássio", "Gabriel", "Lucas", "Pedro", "João", "Gustavo", "Rafael", "Bruno",
            "Diego", "Felipe", "Matheus", "Vinicius", "Arthur", "Henrique", "Daniel"
        );

        sobrenomes = Arrays.asList(
            "Ramos", "Silva", "Santos", "Oliveira", "Souza", "Costa", "Pereira", "Alves",
            "Ferreira", "Rodrigues", "Gomes", "Martins", "Barbosa", "Ribeiro", "Araújo"
        );

        posicoes = Arrays.asList(
            "goleiro", "zagueiro", "lateral-direito", "lateral-esquerdo", "volante",
            "meio-campista", "atacante", "ponta-direita", "ponta-esquerda", "centroavante"
        );

        times = Arrays.asList(
            "Corinthians", "Palmeiras", "São Paulo", "Santos", "Flamengo", "Fluminense",
            "Vasco", "Botafogo", "Grêmio", "Internacional", "Atlético-MG", "Cruzeiro"
        );
    }

    public String gerarJogador() {
        String nome = nomes.get(random.nextInt(nomes.size()));
        String sobrenome = sobrenomes.get(random.nextInt(sobrenomes.size()));
        int idade = 18 + random.nextInt(20); // Idade entre 18 e 37 anos
        String posicao = posicoes.get(random.nextInt(posicoes.size()));
        String time = times.get(random.nextInt(times.size()));

        return String.format("%s %s é um futebolista brasileiro de %d anos que atua como %s. Atualmente defende o %s.",
                nome, sobrenome, idade, posicao, time);
    }

    public void exibirJogador() {
        System.out.println(gerarJogador());
    }
}

package org.example;

import java.util.Arrays;
import java.util.List;
import java.util.Random;
import java.util.Scanner;

public class GeradorPokemon {
    private List<String> nomesPokemon;
    private List<String> tiposPokemon;
    private Random random;

    public GeradorPokemon() {
        this.random = new Random();
        inicializarListas();
    }

    private void inicializarListas() {
        nomesPokemon = Arrays.asList(
            "Pikachu", "Charizard", "Blastoise", "Venusaur", "Gengar", "Alakazam",
            "Machamp", "Golem", "Lapras", "Snorlax", "Dragonite", "Mewtwo",
            "Mew", "Gyarados", "Arcanine", "Rapidash", "Magnezone", "Lucario",
            "Garchomp", "Dialga", "Palkia", "Giratina", "Arceus", "Rayquaza"
        );

        tiposPokemon = Arrays.asList(
            "Elétrico", "Fogo", "Água", "Planta", "Fantasma", "Psíquico",
            "Lutador", "Terra", "Gelo", "Normal", "Dragão", "Voador",
            "Veneno", "Inseto", "Pedra", "Aço", "Sombrio", "Fada"
        );
    }

    public String gerarPokemon() {
        String nome = nomesPokemon.get(random.nextInt(nomesPokemon.size()));
        String tipo = tiposPokemon.get(random.nextInt(tiposPokemon.size()));
        int nivel = 1 + random.nextInt(100); // Nível entre 1 e 100

        return String.format("%s é um Pokémon do tipo %s de nível %d.", nome, tipo, nivel);
    }

    public void gerarMultiplosPokemon(int quantidade) {
        System.out.println("Pokémon gerados:");
        for (int i = 0; i < quantidade; i++) {
            System.out.println((i + 1) + ". " + gerarPokemon());
        }
    }

    public void executarGerador() {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Quantos Pokémon você deseja gerar? ");
        int quantidade = scanner.nextInt();
        gerarMultiplosPokemon(quantidade);
    }
}

package org.example;

import java.util.Random;

public class GeradorSenha {
    private static final String CARACTERES = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    private Random random;

    public GeradorSenha() {
        this.random = new Random();
    }

    public String gerarSenha(int tamanho) {
        StringBuilder senha = new StringBuilder();

        for (int i = 0; i < tamanho; i++) {
            int indice = random.nextInt(CARACTERES.length());
            senha.append(CARACTERES.charAt(indice));
        }

        return senha.toString();
    }

    public void exibirSenha() {
        String senha = gerarSenha(8);
        System.out.println("Senha gerada: " + senha);
    }
}

