package org.example;

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== LISTA 002 - Classe Random ===\n");

        // Exercício 1: Gerador de Senhas
        System.out.println("1. GERADOR DE SENHAS");
        System.out.println("-------------------");
        GeradorSenha geradorSenha = new GeradorSenha();
        geradorSenha.exibirSenha();
        System.out.println();

        // Exercício 2: Gerador de Jogador
        System.out.println("2. GERADOR DE JOGADOR");
        System.out.println("---------------------");
        GeradorJogador geradorJogador = new GeradorJogador();
        geradorJogador.exibirJogador();
        System.out.println();

        // Exercício 3: Gerador de Pokémon
        System.out.println("3. GERADOR DE POKÉMON");
        System.out.println("---------------------");
        GeradorPokemon geradorPokemon = new GeradorPokemon();
        geradorPokemon.executarGerador();

        scanner.close();
    }
}
